using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using System.Reflection;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace YunJian.Riichi.Editor {
 [InitializeOnLoad] public static class RankStickR10Review {
  const string Key="RankStickR10";
  static RankStickR10Review(){EditorApplication.update+=()=>{if(EditorApplication.isPlaying&&!EditorApplication.isCompiling&&SessionState.GetBool(Key,false)){SessionState.SetBool(Key,false);UnityEngine.Object.FindAnyObjectByType<RiichiClient>().gameObject.AddComponent<RankStickR10Capture>();}};}
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)] static void Bootstrap(){if(!SessionState.GetBool(Key,false))return;PlayerRecord.PreviewOnly=true;CharacterRoster.PreviewOnly=true;CharacterPackService.RootOverride=Environment.GetEnvironmentVariable("YUNJIAN_R10_REPO")+"/build/character-voice-r34/roles";CharacterPackService.RespectPreviewAvailability=true;CharacterPackService.ResetForReview();WardrobePackService.RespectPreviewAvailability=true;WardrobePackService.RootOverride=Environment.GetEnvironmentVariable("YUNJIAN_R10_OUT")+"/empty-packs";}
  public static void Run(){PlayerSettings.companyName="YunJianReview";PlayerSettings.productName="RankStickR10";EditorSceneManager.OpenScene("Assets/Scenes/Table.unity");SessionState.SetBool(Key,true);EditorApplication.isPlaying=true;}
 }
 public sealed class RankStickR10Capture:MonoBehaviour {
  const BindingFlags Private=BindingFlags.Instance|BindingFlags.NonPublic;
  [Serializable] class Row {public string id,name;public int meshes;public List<Vector3> centers=new List<Vector3>();}
  [Serializable] class Report {public int checks;public List<string> passed=new List<string>();public List<Row> sticks=new List<Row>();public bool androidDeviceTested;}
  RiichiClient client;LobbyController lobby;TableRenderer table;string output;Report report=new Report();System.Diagnostics.Process encoder;RenderTexture rt;Texture2D pixels;int frame;string chapter;readonly List<string> chapters=new List<string>();
  void Check(bool ok,string reason){if(!ok)throw new Exception(reason);report.checks++;report.passed.Add(reason);}
  IEnumerator Frames(int n=8){for(int i=0;i<n;i++)yield return null;}
  IEnumerator Shot(string name){yield return Frames();yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(output+"/"+name+".png",t.EncodeToPNG());Destroy(t);}
  void StartFilm(){rt=new RenderTexture(1600,900,0,RenderTextureFormat.ARGB32);rt.Create();pixels=new Texture2D(1600,900,TextureFormat.RGB24,false);string repo=Environment.GetEnvironmentVariable("YUNJIAN_R10_REPO");encoder=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo{FileName=@"C:\Users\Rtyu3221\.cache\codex-runtimes\codex-primary-runtime\dependencies\python\python.exe",Arguments="-X utf8 \""+repo+"/scripts/encode-unity-capture-r40.py\" --output \""+output+"/r10-raw.mp4\" --width 1600 --height 900 --fps 20",UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardError=true});}
  IEnumerator Film(string label,float seconds,Action<int> act=null){chapter=label;chapters.Add(frame+" "+label);for(int i=0;i<Mathf.RoundToInt(seconds*20);i++){act?.Invoke(i);yield return null;yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshotIntoRenderTexture(rt);var prior=RenderTexture.active;RenderTexture.active=rt;pixels.ReadPixels(new Rect(0,0,1600,900),0,0);RenderTexture.active=prior;var bytes=pixels.GetRawTextureData();encoder.StandardInput.BaseStream.Write(bytes,0,bytes.Length);frame++;}}
  IEnumerator Start(){output=Environment.GetEnvironmentVariable("YUNJIAN_R10_OUT");Directory.CreateDirectory(output);client=GetComponent<RiichiClient>();table=GetComponent<TableRenderer>();client.SessionPreviewOnly=true;client.BeginLobbyValidation("r10-local");lobby=client.Lobby;GetComponent<ResourceRoomCoordinator>().enabled=false;GetComponent<CharacterPackService>().StopAllCoroutines();GetComponent<WardrobePackService>().StopAllCoroutines();WardrobePackService.RespectPreviewAvailability=false;WardrobePackService.ResetForReview();AudioListener.volume=0;
   var stack=new Stack<IEnumerator>();stack.Push(Run());while(stack.Count>0){object next;try{var t=stack.Peek();if(!t.MoveNext()){stack.Pop();continue;}next=t.Current;if(next is IEnumerator nested){stack.Push(nested);continue;}}catch(Exception e){if(encoder!=null&&!encoder.HasExited)encoder.Kill();File.WriteAllText(output+"/failed.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);yield break;}yield return next;}
   encoder.StandardInput.Close();while(!encoder.HasExited)yield return null;Check(encoder.ExitCode==0,"video encoded");File.WriteAllText(output+"/report.json",JsonUtility.ToJson(report,true));File.WriteAllLines(output+"/chapters.txt",chapters);EditorApplication.Exit(0);
  }
  RoomView Final(string key,string category,int n,int place,int score){var v=DressPreviewStates.Base(key,new WardrobeLoadout(),"yiji",400101,"云间牌友");v.players=v.players.Take(n).ToArray();v.n=n;v.phase="result";v.lobby.category=category;v.players[0].score=score;v.result=new ResultView{title="终局",delta=new int[n],details=new WinDetail[0],matchOver=true,rules=new ResultRules{n=n,rounds=2,start=n==3?35000:25000,category=category},standings=Enumerable.Range(0,n).Select(i=>new StandingView{seat=i,place=i==0?place:(i<place?i:i+1),score=i==0?score:25000,bot=i!=0,stats=new SeatStats()}).ToArray()};return v;}
  IEnumerator RankCase(string label,int n,int level,int points,int place,int score){PlayerRecord.Replace(new PlayerRecordData{rank4=new RankState(level,points),rank3=new RankState(level,points)});var v=Final(label,"friend",n,place,score);var c=PlayerRecord.Record(v);Check(c!=null,"friend awards rank "+label);int after=PlayerRecord.Rank(n).points;Check(PlayerRecord.Record(v)==c&&PlayerRecord.Rank(n).points==after,"terminal poll is idempotent "+label);client.ShowValidationFixture(v);var display=(ResultPresentation)typeof(RiichiClient).GetField("resultDisplay",Private).GetValue(client);display.Observe(v);display.Freeze=true;display.FrozenAge=100;display.Advance(v);Check(display.ShowingFinal,"standings before rank "+label);yield return Film(label+"-终局",.5f);display.Advance(v);Check(display.ShowingRank,"independent rank page "+label);float end=display.RankAnimationEnd(v);yield return Film(label+"-段位积分",end+1.5f,i=>display.FrozenAge=i/20f);Check(display.RankDisplayState(v,end+.1f).points==c.after.points&&display.RankDisplayState(v,end+.1f).level==c.after.level,"rank animation final values "+label);yield return Shot(label);}
  IEnumerator Run(){var game=EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));game.GetType().GetMethod("SetCustomResolution",Private).Invoke(game,new object[]{new Vector2(1600,900),"Rank stick R10"});yield return Frames(15);StartFilm();PlayerRecord.Replace(new PlayerRecordData{rank4=new RankState(4,354),rank3=new RankState(7,660)});lobby.Home();yield return Frames(30);yield return Film("大厅-四麻",1);lobby.ValidationPress("swapRank");yield return Frames();Check(PlayerRecord.LobbyRankPlayers==3,"small badge switches to sanma");Check(lobby.Page==LobbyController.ScreenPage.Home&&!lobby.OverlayActive,"badge does not open profile");yield return Film("大厅-三麻",1);lobby.ValidationPress("swapRank");yield return Frames();Check(PlayerRecord.LobbyRankPlayers==4,"badge switches back to yonma");yield return Shot("lobby-yonma");
   yield return RankCase("四麻加分",4,3,300,1,41200);yield return RankCase("三麻加分",3,3,300,1,50000);yield return RankCase("升段",4,3,590,1,41200);yield return RankCase("降段",4,6,5,4,10000);yield return RankCase("魂天",4,15,100,1,41200);
   PlayerRecord.Replace(new PlayerRecordData());var competition=Final("competition","competition",4,1,41200);Check(PlayerRecord.Record(competition)==null,"competition remains separate from rank");
   foreach(var item in WardrobeCatalog.Items("stick")){
    var v=DressPreviewStates.Base("stick-"+item.id,new WardrobeLoadout(),"yiji",400101,item.name);for(int i=0;i<4;i++){v.players[i].wardrobe=new WardrobeLoadout{stick=item.id};v.players[i].riichi=1;}client.ShowValidationFixture(v);yield return Frames(12);var row=new Row{id=item.id,name=item.name};
    for(int seat=0;seat<4;seat++){var stick=table.StickTarget(seat);Check(stick!=null,item.id+" seat "+seat+" deposited");var renderers=stick.GetComponentsInChildren<MeshRenderer>().Where(r=>r.enabled&&r.gameObject.activeInHierarchy).ToArray();Check(renderers.Length>0,item.id+" seat "+seat+" has body");row.meshes+=renderers.Length;row.centers.Add(table.Camera.WorldToScreenPoint(stick.position));foreach(var r in renderers)Check(r.sharedMaterials.All(m=>m!=null&&m.shader.isSupported),item.id+" shader "+r.name);}
    report.sticks.Add(row);yield return Shot("stick-"+item.id);yield return Film(item.name+"（自家／下家／对家／上家）",1.5f);Debug.Log("R10 STICK "+item.id);
   }
  }
 }
}
